import { helpTopics } from './content';

const escape = (value: string) => value.replace(/[\\`*_[\]<>]/g, '\\$&');
const link = (id: string) => `[${helpTopics.find(topic => topic.id === id)!.title}](#help-${id})`;

export function renderHelpManual(version: string): string {
  const lines = ['# GateRunner help', '', `User guide for **${version}**.`, '',
    'This manual and the searchable in-app help share one source. In the app, use the Help button or F1; editor Help buttons open the relevant topic.', '',
    '<!-- Generated by yarn help:generate. Edit src/help/content.ts, not this file. -->', '', '## Table of contents', ''];
  for (const group of new Set(helpTopics.map(topic => topic.group))) {
    lines.push(`### ${group}`, '', ...helpTopics.filter(topic => topic.group === group).map(topic => `- ${link(topic.id)}`), '');
  }
  for (const topic of helpTopics) {
    lines.push(`<a id="help-${topic.id}"></a>`, '', `## ${topic.title}`, '', escape(topic.summary), '', `**Where:** ${escape(topic.location)}`, '');
    for (const section of topic.sections) {
      lines.push(`### ${section.title}`, '');
      for (const paragraph of section.paragraphs ?? []) lines.push(escape(paragraph), '');
      if (section.bullets) lines.push(...section.bullets.map(item => `- ${escape(item)}`), '');
      if (section.steps) lines.push(...section.steps.map((item, index) => `${index + 1}. ${escape(item)}`), '');
      if (section.table) {
        const row = (cells: string[]) => `| ${cells.map(cell => escape(cell).replace(/\|/g, '\\|')).join(' | ')} |`;
        lines.push(row(section.table.headings), row(section.table.headings.map(() => '---')), ...section.table.rows.map(row), '');
      }
      if (section.code) lines.push('```text', section.code, '```', '');
      if (section.topics) lines.push(...section.topics.map(id => `- ${link(id)}`), '');
      if (section.links) lines.push(...section.links.map(item => `- [${item.label}](${item.href})`), '');
    }
    lines.push(`**Related:** ${topic.related.map(link).join(' · ')}`, '', '[Back to contents](#table-of-contents)', '');
  }
  return lines.join('\n');
}
